(4818500, 695846, 49683, '<td valign="top">Very nice 10</td>', 'Very nice 10', '2008-07-11 02:19:09.000000', NULL, 1),
(4818508, 697085, 55343, '<td valign="top">This picture seems to lack a very captivating subject. Without the challenge and without the title, had I seen this image I would just think, ''a fence?''. You know what I mean? It just doesnt hold my interest. Fences can make interesting subjects but this just seems kind of bland. That might be partially helped by shooting from a different point of view, maybe closer or with more detail on the part that is actually weathered. Hope that was remotely helpful :)</td>', 'This picture seems to lack a very captivating subject. Without the challenge and without the title, had I seen this image I would just think, ''a fence?''. You know what I mean? It just doesnt hold my interest. Fences can make interesting subjects but this just seems kind of bland. That might be partially helped by shooting from a different point of view, maybe closer or with more detail on the part that is actually weathered. Hope that was remotely helpful :)', '2008-07-11 02:31:35.000000', NULL, 1),
(4818511, 697066, 55343, '<td valign="top">Good composition</td>', 'Good composition', '2008-07-11 02:35:00.000000', NULL, 1),
(4818514, 695167, 55343, '<td valign="top">Wow good subject, that has got to be the most weathered thing I have seen so far. Looks like if the wind ever blows very hard it''s a goner.</td>', 'Wow good subject, that has got to be the most weathered thing I have seen so far. Looks like if the wind ever blows very hard it''s a goner.', '2008-07-11 02:37:25.000000', NULL, 1),
(4818520, 695882, 55343, '<td valign="top">This picture doesn''t look like it''s taking advantage of the maximum size allowed on challenges, typically larger pictures have better impact, at least on voters. It really is quite pretty.</td>', 'This picture doesn''t look like it''s taking advantage of the maximum size allowed on challenges, typically larger pictures have better impact, at least on voters. It really is quite pretty.', '2008-07-11 02:40:22.000000', NULL, 1),
