(4820311, 697098, 95590, '<td valign="top">This is great although I am not sure I like the fisheye effect. I''d have liked it without distortion.</td>', 'This is great although I am not sure I like the fisheye effect. I''d have liked it without distortion.', '2008-07-12 02:08:15.000000', NULL, 1),
(4820312, 695228, 95590, '<td valign="top">Nice composition but too much sharpening has created a halo effect. If properly done this could be a beautiful photo. Still great - especially the old against the new.</td>', 'Nice composition but too much sharpening has created a halo effect. If properly done this could be a beautiful photo. Still great - especially the old against the new.', '2008-07-12 02:09:29.000000', NULL, 1),
(4820314, 695377, 95590, '<td valign="top">Harsh contrasts and mix of metal and wood textures give this one a great feeling. I can almost hear the door creek. Composition is perfect for this.</td>', 'Harsh contrasts and mix of metal and wood textures give this one a great feeling. I can almost hear the door creek. Composition is perfect for this.', '2008-07-12 02:11:51.000000', NULL, 1),
(4820323, 696565, 95590, '<td valign="top">Wow. The Old Gent surely must have lots of stories to tell - of fancy dresses, tuxedos and polished shoes, of expensive perfumes and vintage wines, of shy smiles and hearty chuckles, and of the steely stare of the weathered businessman at the passing roads. Oh yes, this is perfect. I love it so.</td>', 'Wow. The Old Gent surely must have lots of stories to tell - of fancy dresses, tuxedos and polished shoes, of expensive perfumes and vintage wines, of shy smiles and hearty chuckles, and of the steely stare of the weathered businessman at the passing roads. Oh yes, this is perfect. I love it so.', '2008-07-12 02:24:33.000000', NULL, 1),
(4820332, 695976, 95590, '<td valign="top">I like how the weathered and the fresh have be placed together here. Good composition too!</td>', 'I like how the weathered and the fresh have be placed together here. Good composition too!', '2008-07-12 02:33:32.000000', NULL, 1),
(4820334, 696033, 95590, '<td valign="top">Very peculiar!</td>', 'Very peculiar!', '2008-07-12 02:39:45.000000', NULL, 1),
(4820338, 697003, 95590, '<td valign="top">Oh yes! There is something about a worn out truck used as a garden prop. I wonder if there''s someone who could tell stories about it. nice!</td>', 'Oh yes! There is something about a worn out truck used as a garden prop. I wonder if there''s someone who could tell stories about it. nice!', '2008-07-12 02:40:57.000000', NULL, 1),
(4820339, 696179, 95590, '<td valign="top">I like this a lot. Very pleasing tones and good composition.</td>', 'I like this a lot. Very pleasing tones and good composition.', '2008-07-12 02:41:52.000000', NULL, 1),
(4820341, 697010, 95590, '<td valign="top">Wonderful!!</td>', 'Wonderful!!', '2008-07-12 02:43:00.000000', NULL, 1),
(4820343, 696031, 95590, '<td valign="top">Nice! Those gloves startled me. :)</td>', 'Nice! Those gloves startled me. :)', '2008-07-12 02:44:31.000000', NULL, 1),
(4820344, 696609, 95590, '<td valign="top">Oh so wonderful. Couldn''t have been any better in color. BW does this one justice.</td>', 'Oh so wonderful. Couldn''t have been any better in color. BW does this one justice.', '2008-07-12 02:45:13.000000', NULL, 1),
(4820345, 697078, 95590, '<td valign="top">Lovely. I''d have liked a bit more of DOF here.</td>', 'Lovely. I''d have liked a bit more of DOF here.', '2008-07-12 02:46:57.000000', NULL, 1),
(4820346, 696514, 95590, '<td valign="top">Favourite! Such a colourful and fun photo.</td>', 'Favourite! Such a colourful and fun photo.', '2008-07-12 02:47:32.000000', NULL, 1),
(4820404, 695226, 46918, '<td valign="top">I love the pic..good job</td>', 'I love the pic..good job', '2008-07-12 04:35:23.000000', NULL, 1),
(4820464, 695634, 42262, '<td valign="top">Well done</td>', 'Well done', '2008-07-12 07:40:44.000000', NULL, 1),
(4820532, 695471, 67152, '<td valign="top">beautiful old mill building - the very bright sky at the top really draws my attention away from the scene - a different crop may have made all the difference here</td>', 'beautiful old mill building - the very bright sky at the top really draws my attention away from the scene - a different crop may have made all the difference here', '2008-07-12 08:37:44.000000', NULL, 1),
(4820533, 696156, 67152, '<td valign="top">splendid scene - the grasses, the reflection in the broken glass - the warm feel of the warm wood - excellent, just excellent</td>', 'splendid scene - the grasses, the reflection in the broken glass - the warm feel of the warm wood - excellent, just excellent', '2008-07-12 08:38:36.000000', NULL, 1),
(4820722, 696870, 3087, '<td valign="top">Wow, what a clever shot... really like it.</td>', 'Wow, what a clever shot... really like it.', '2008-07-12 11:50:26.000000', NULL, 1),
(4820726, 695514, 3087, '<td valign="top">I like the way you''ve used the bow to create such a strong diagonal in the image. Compositions works well. As does lvely colours of the grass, sky and rust.</td>', 'I like the way you''ve used the bow to create such a strong diagonal in the image. Compositions works well. As does lvely colours of the grass, sky and rust.', '2008-07-12 11:53:56.000000', NULL, 1),
(4820727, 696934, 3087, '<td valign="top">I love worn paintwork on bricks!</td>', 'I love worn paintwork on bricks!', '2008-07-12 11:54:26.000000', NULL, 1),
(4820728, 696441, 3087, '<td valign="top">Lovely textures and shapes creating some lovely light and shadow.</td>', 'Lovely textures and shapes creating some lovely light and shadow.', '2008-07-12 11:54:51.000000', NULL, 1),
(4820730, 695759, 3087, '<td valign="top">Fascinating! Is this an image of an eye projected onto a weathered surface? I can''t quite make it out but it''s intriguing.</td>', 'Fascinating! Is this an image of an eye projected onto a weathered surface? I can''t quite make it out but it''s intriguing.', '2008-07-12 11:55:55.000000', NULL, 1),
(4820800, 696906, 30251, '<td valign="top">I''d like to see a little more color and the crop is a little tight on the closer wing. Nice shot overall.</td>', 'I''d like to see a little more color and the crop is a little tight on the closer wing. Nice shot overall.', '2008-07-12 13:04:10.000000', NULL, 1),
(4820801, 696933, 30251, '<td valign="top">I''d love it is was tack sharp. Nice use of the white as negative space.</td>', 'I''d love it is was tack sharp. Nice use of the white as negative space.', '2008-07-12 13:04:55.000000', NULL, 1),
(4820802, 696724, 30251, '<td valign="top">great use of the black and white. Love the warm tones.</td>', 'great use of the black and white. Love the warm tones.', '2008-07-12 13:05:23.000000', NULL, 1),
(4820803, 696955, 30251, '<td valign="top">Over processed, IMHO.</td>', 'Over processed, IMHO.', '2008-07-12 13:06:01.000000', NULL, 1),
(4820805, 697049, 30251, '<td valign="top">Nice character study. Interesting crop, I think I''d like to see more or less of his face.</td>', 'Nice character study. Interesting crop, I think I''d like to see more or less of his face.', '2008-07-12 13:07:30.000000', NULL, 1),
(4820806, 695861, 30251, '<td valign="top">Great crop, ok lighting. Love to see it with a bit more contrast or reshot with less soft light.</td>', 'Great crop, ok lighting. Love to see it with a bit more contrast or reshot with less soft light.', '2008-07-12 13:08:29.000000', NULL, 1),
(4820808, 695551, 30251, '<td valign="top">Nice shot, love to see a more color and depth in the sky. I guess you can''t summon up a big blue patch on request though?<br/> <br/>The shaddows might be a bit dark as well.</td>', 'Nice shot, love to see a more color and depth in the sky. I guess you can''t summon up a big blue patch on request though? The shaddows might be a bit dark as well.', '2008-07-12 13:09:59.000000', NULL, 1),
(4820811, 696983, 30251, '<td valign="top">Love the shot, not crazy about the border.</td>', 'Love the shot, not crazy about the border.', '2008-07-12 13:10:43.000000', NULL, 1),
(4820812, 697010, 30251, '<td valign="top">great light! the crop is a little tight for my taste.</td>', 'great light! the crop is a little tight for my taste.', '2008-07-12 13:11:12.000000', NULL, 1),
(4820813, 695759, 30251, '<td valign="top">Nice find.</td>', 'Nice find.', '2008-07-12 13:11:30.000000', NULL, 1),
(4820816, 696636, 30251, '<td valign="top">a little more saturation? nice use of dof.</td>', 'a little more saturation? nice use of dof.', '2008-07-12 13:12:02.000000', NULL, 1),
(4820818, 696912, 30251, '<td valign="top">it''s kind of a boring composition, needs a little directional lighting.</td>', 'it''s kind of a boring composition, needs a little directional lighting.', '2008-07-12 13:13:05.000000', NULL, 1),
(4820821, 696991, 30251, '<td valign="top">I think this composition is a little too centered, or maybe not centered enough . . .</td>', 'I think this composition is a little too centered, or maybe not centered enough . . .', '2008-07-12 13:14:20.000000', NULL, 1),
(4820823, 697007, 30251, '<td valign="top">Are you talking about the roof being weathered? I don''t know if this shot showcases the challenge. It''s a beautiful shot though.</td>', 'Are you talking about the roof being weathered? I don''t know if this shot showcases the challenge. It''s a beautiful shot though.', '2008-07-12 13:15:48.000000', NULL, 1),
(4820825, 695514, 30251, '<td valign="top">nice find, what a cool shot.</td>', 'nice find, what a cool shot.', '2008-07-12 13:16:18.000000', NULL, 1),
(4820830, 696868, 30251, '<td valign="top">nice and dramatic sky, maybe a little much with the halo around the tree and all.</td>', 'nice and dramatic sky, maybe a little much with the halo around the tree and all.', '2008-07-12 13:20:25.000000', NULL, 1),
(4820832, 696441, 30251, '<td valign="top">beautiful</td>', 'beautiful', '2008-07-12 13:21:01.000000', NULL, 1),
(4820835, 697033, 30251, '<td valign="top">Nice lines. I''m not sure the b&amp;w showcases the "weathered" part of this location.</td>', 'Nice lines. I''m not sure the b&w showcases the "weathered" part of this location.', '2008-07-12 13:22:44.000000', NULL, 1),
(4820836, 696865, 30251, '<td valign="top">take the flash off the camera.</td>', 'take the flash off the camera.', '2008-07-12 13:23:07.000000', NULL, 1),
(4820837, 696000, 30251, '<td valign="top">cool and nostalgic</td>', 'cool and nostalgic', '2008-07-12 13:23:26.000000', NULL, 1),
(4820839, 696259, 30251, '<td valign="top">needs contrast, what happen to the black point?</td>', 'needs contrast, what happen to the black point?', '2008-07-12 13:23:53.000000', NULL, 1),
(4820840, 695439, 30251, '<td valign="top">Nice work, great use of the BW.</td>', 'Nice work, great use of the BW.', '2008-07-12 13:24:34.000000', NULL, 1),
(4820841, 696670, 30251, '<td valign="top">Very cool location. Would have love to see this shot during "magic hour."</td>', 'Very cool location. Would have love to see this shot during "magic hour."', '2008-07-12 13:25:26.000000', NULL, 1),
(4820842, 697084, 30251, '<td valign="top">Does mostly destroyed count as weathered? :)<br/> <br/>Looks a little grainy to me, other than that it looks great.</td>', 'Does mostly destroyed count as weathered? :) Looks a little grainy to me, other than that it looks great.', '2008-07-12 13:26:39.000000', NULL, 1),
(4820845, 697094, 30251, '<td valign="top">cool shot, a little over processed for me, like the fill flash + sunlight look.</td>', 'cool shot, a little over processed for me, like the fill flash + sunlight look.', '2008-07-12 13:28:21.000000', NULL, 1),
(4821169, 697103, 27421, '<td valign="top">Good.</td>', 'Good.', '2008-07-12 18:44:26.000000', NULL, 1),
(4821206, 695947, 76598, '<td valign="top">Gave you a 7, technically a great image (focus and exposure are right on), the distance to the house causes the weathering to be less obvious and I have never cared for the distortion caused by a wide angle lens.</td>', 'Gave you a 7, technically a great image (focus and exposure are right on), the distance to the house causes the weathering to be less obvious and I have never cared for the distortion caused by a wide angle lens.', '2008-07-12 19:25:05.000000', NULL, 1),
(4821207, 696992, 76598, '<td valign="top">Scored this well, technically it is great, the PP is a little more than I would like and it has an abstract quality that does not necessarily say weathered and does not totally come across as a photograph</td>', 'Scored this well, technically it is great, the PP is a little more than I would like and it has an abstract quality that does not necessarily say weathered and does not totally come across as a photograph', '2008-07-12 19:26:37.000000', NULL, 1),
(4821208, 696514, 76598, '<td valign="top">well exposed, good color, I might have been tempted to saturate the colors a little more, the glare on a couple of the buoys are a bother.</td>', 'well exposed, good color, I might have been tempted to saturate the colors a little more, the glare on a couple of the buoys are a bother.', '2008-07-12 19:28:01.000000', NULL, 1),
(4821214, 697048, 76598, '<td valign="top">Scored this well, but I don''t really care for this much processing and some how the centering of the building doesn''t create interest or cause your eye to explore the image.  It is obvious that the building is weathered, but some of that is lost in the processing.</td>', 'Scored this well, but I don''t really care for this much processing and some how the centering of the building doesn''t create interest or cause your eye to explore the image.  It is obvious that the building is weathered, but some of that is lost in the processing.', '2008-07-12 19:29:28.000000', NULL, 1),
(4821216, 696701, 76598, '<td valign="top">a visually intriguing image and I hope it scores well.  It seems that you can see the wind pushing it, but I don''t know what it is causing that illusion.  Somehow I would like more DOF, but at the same time the shallowness adds to the image.  I almost marked this down because the leaf really doesn''t look weathered.  Great image, wish I had taken it.</td>', 'a visually intriguing image and I hope it scores well.  It seems that you can see the wind pushing it, but I don''t know what it is causing that illusion.  Somehow I would like more DOF, but at the same time the shallowness adds to the image.  I almost marked this down because the leaf really doesn''t look weathered.  Great image, wish I had taken it.', '2008-07-12 19:31:33.000000', NULL, 1),
(4821217, 696983, 76598, '<td valign="top">Very nice, the light is good, color and contrast are good.  Are the darkened edges allowed in Basic Editing?</td>', 'Very nice, the light is good, color and contrast are good.  Are the darkened edges allowed in Basic Editing?', '2008-07-12 19:31:41.000000', NULL, 1),
(4821219, 696574, 76598, '<td valign="top">I am sure this is scoring well.  I know it would have been tricky on exposure, but I would have liked to have seen more detail in his hat.  I would also like to see a little bit more eye.</td>', 'I am sure this is scoring well.  I know it would have been tricky on exposure, but I would have liked to have seen more detail in his hat.  I would also like to see a little bit more eye.', '2008-07-12 19:33:23.000000', NULL, 1),
(4821220, 696430, 76598, '<td valign="top">I really like this and think it might do well.  IMO waiting until later in the day when the light was a little softer on the dash might have improved the image.  You lose a lot in the dash and windows</td>', 'I really like this and think it might do well.  IMO waiting until later in the day when the light was a little softer on the dash might have improved the image.  You lose a lot in the dash and windows', '2008-07-12 19:33:38.000000', NULL, 1),
(4821242, 696600, 83313, '<td valign="top">They look like giant cigarettes sticking out of the ground!</td>', 'They look like giant cigarettes sticking out of the ground!', '2008-07-12 20:08:33.000000', NULL, 1),
(4821244, 696610, 83313, '<td valign="top">I like the partial desaturation. It gives this a bit of an antique look</td>', 'I like the partial desaturation. It gives this a bit of an antique look', '2008-07-12 20:09:31.000000', NULL, 1),
(4821246, 696918, 83313, '<td valign="top">White balance is really off here, giving it a yellow color cast. You usually  need to use a WB setting of tungsten or fluorescent to avoid the yellow cast under artificial light.</td>', 'White balance is really off here, giving it a yellow color cast. You usually  need to use a WB setting of tungsten or fluorescent to avoid the yellow cast under artificial light.', '2008-07-12 20:12:16.000000', NULL, 1),
(4821248, 696062, 83313, '<td valign="top">I like the partial desat. It gives it a creepy look. I find the crop a touch too tight for my taste.</td>', 'I like the partial desat. It gives it a creepy look. I find the crop a touch too tight for my taste.', '2008-07-12 20:13:42.000000', NULL, 1),
(4821250, 695566, 83313, '<td valign="top">Interesting choice of B/W for a shot like this. It does enhance the texture, and I give you kudos for trying this on something almost always done in strong colors.</td>', 'Interesting choice of B/W for a shot like this. It does enhance the texture, and I give you kudos for trying this on something almost always done in strong colors.', '2008-07-12 20:15:11.000000', NULL, 1),
(4821409, 696441, 74911, '<td valign="top">Excellent details, nice subject, good lighitng.</td>', 'Excellent details, nice subject, good lighitng.', '2008-07-12 23:45:54.000000', NULL, 1),
(4821410, 696471, 74911, '<td valign="top">Great subject, good sharpness. Lacks a bit of contrast in my opnion, which I guess you would have delibrately done to save the clouds from being washed out. But a good one!</td>', 'Great subject, good sharpness. Lacks a bit of contrast in my opnion, which I guess you would have delibrately done to save the clouds from being washed out. But a good one!', '2008-07-12 23:45:58.000000', NULL, 1),
(4821411, 696983, 74911, '<td valign="top">A common subject in this challenge. But you have handled it very well. Good lighting and great post processing.</td>', 'A common subject in this challenge. But you have handled it very well. Good lighting and great post processing.', '2008-07-12 23:46:01.000000', NULL, 1),
(4821412, 695637, 74911, '<td valign="top">I like the contrast and the softness in the picture. Am waiting to see your note, to understand how you achieved this. Good job!</td>', 'I like the contrast and the softness in the picture. Am waiting to see your note, to understand how you achieved this. Good job!', '2008-07-12 23:46:04.000000', NULL, 1),
(4821413, 696576, 74911, '<td valign="top">Great subject, appropriate lighting. A bit of increase in sharpness and contrast would have made this great shot a greater one.</td>', 'Great subject, appropriate lighting. A bit of increase in sharpness and contrast would have made this great shot a greater one.', '2008-07-12 23:46:08.000000', NULL, 1),
(4821414, 695777, 74911, '<td valign="top">Excellent shot.</td>', 'Excellent shot.', '2008-07-12 23:46:15.000000', NULL, 1),
(4821415, 696870, 74911, '<td valign="top">Great composition and placement of the subject.</td>', 'Great composition and placement of the subject.', '2008-07-12 23:46:18.000000', NULL, 1),
(4821416, 696543, 74911, '<td valign="top">Good lighting and details. A very different subject from a series of broken vehicles and barns.</td>', 'Good lighting and details. A very different subject from a series of broken vehicles and barns.', '2008-07-12 23:46:23.000000', NULL, 1),
(4821417, 696821, 74911, '<td valign="top">Reminds me of Ansel Adams'' shots. Great compo and contrast. Overall a good B&amp;W image.</td>', 'Reminds me of Ansel Adams'' shots. Great compo and contrast. Overall a good B&W image.', '2008-07-12 23:46:26.000000', NULL, 1),
(4821419, 697094, 74911, '<td valign="top">Nice play with light here.</td>', 'Nice play with light here.', '2008-07-12 23:47:19.000000', NULL, 1),
(4821421, 696678, 74911, '<td valign="top">I like the clever use of shutter speed to pull attention to the waves, though there is another important focal point, that is the eroded land. BTW, is the sky really so blue or is it overdone?</td>', 'I like the clever use of shutter speed to pull attention to the waves, though there is another important focal point, that is the eroded land. BTW, is the sky really so blue or is it overdone?', '2008-07-12 23:47:25.000000', NULL, 1),
(4821423, 696371, 74911, '<td valign="top">Excellent color, composition and details.</td>', 'Excellent color, composition and details.', '2008-07-12 23:47:36.000000', NULL, 1),
(4821424, 696969, 74911, '<td valign="top">A typical subject which I was looking for and failed. You have made the best use of it. Excellent shot.</td>', 'A typical subject which I was looking for and failed. You have made the best use of it. Excellent shot.', '2008-07-12 23:47:40.000000', NULL, 1),
(4821425, 695514, 74911, '<td valign="top">A bit of more sharpness would have made this a great shot.</td>', 'A bit of more sharpness would have made this a great shot.', '2008-07-12 23:47:45.000000', NULL, 1),
(4821426, 696982, 74911, '<td valign="top">Very unusual approach to this challenge. Good one.</td>', 'Very unusual approach to this challenge. Good one.', '2008-07-12 23:47:47.000000', NULL, 1),
(4821430, 695759, 74911, '<td valign="top">No idea how you got this. But, an excellent shot.</td>', 'No idea how you got this. But, an excellent shot.', '2008-07-12 23:50:08.000000', NULL, 1),
(4821456, 696868, 65234, '<td valign="top">Nice title; I can really see that in the building''s shape.  I like the lines of light/clouds pointing to the house (or emanating from the spaceship behind the trees, depending on how fanciful I''m feeling).</td>', 'Nice title; I can really see that in the building''s shape.  I like the lines of light/clouds pointing to the house (or emanating from the spaceship behind the trees, depending on how fanciful I''m feeling).', '2008-07-13 00:23:06.000000', NULL, 1),
(4821461, 697074, 65234, '<td valign="top">Are you trying to make me sing Christmas carols?  ''Cuz it worked ;-p<br/> <br/>Good choice of subject for the challenge.  Was there more bell on the left/bottom?  If so, I''d tilt the composition to eliminate anything non-bell (like the board).  If not, maybe tightent the crop some.</td>', 'Are you trying to make me sing Christmas carols?  ''Cuz it worked ;-p Good choice of subject for the challenge.  Was there more bell on the left/bottom?  If so, I''d tilt the composition to eliminate anything non-bell (like the board).  If not, maybe tightent the crop some.', '2008-07-13 00:25:57.000000', NULL, 1),
(4821463, 696492, 65234, '<td valign="top">Distilled?  Part of it looks suspiciously clean and shiny.  But that gets a nice reflection of trees which reinforces the idea of a moonshine still.</td>', 'Distilled?  Part of it looks suspiciously clean and shiny.  But that gets a nice reflection of trees which reinforces the idea of a moonshine still.', '2008-07-13 00:27:36.000000', NULL, 1),
(4821464, 696688, 65234, '<td valign="top">:(((  Not a typical subject but he does look pretty beat up and tired.</td>', ':(((  Not a typical subject but he does look pretty beat up and tired.', '2008-07-13 00:29:18.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4821465, 697096, 65234, '<td valign="top">I think they may break if you hit them.</td>', 'I think they may break if you hit them.', '2008-07-13 00:30:11.000000', NULL, 1),
(4821466, 695645, 65234, '<td valign="top">Awesome subject!  Actually, I''d love to see the whole thing.<br/> <br/>This feels a little off-kilter but with some of those horizontals not being parallel to each other it may be an optical illusion.</td>', 'Awesome subject!  Actually, I''d love to see the whole thing. This feels a little off-kilter but with some of those horizontals not being parallel to each other it may be an optical illusion.', '2008-07-13 00:32:19.000000', NULL, 1),
(4821469, 696883, 65234, '<td valign="top">Nice find, and I like the juxtaposition of the old wood and the bright flowers.  Yellows and whites look a bit blown out on my monitor.</td>', 'Nice find, and I like the juxtaposition of the old wood and the bright flowers.  Yellows and whites look a bit blown out on my monitor.', '2008-07-13 00:34:06.000000', NULL, 1),
