(4821601, 696656, 61367, '<td valign="top">i think it would''ve helped if it was in color</td>', 'i think it would''ve helped if it was in color', '2008-07-13 03:23:42.000000', NULL, 1),
(4821604, 696362, 61367, '<td valign="top">loretta &amp; leroy - sweet</td>', 'loretta & leroy - sweet', '2008-07-13 03:27:13.000000', NULL, 1),
